const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

// CI/CD Pipeline Audit Logger Service
// Receives webhook events from build systems and logs them securely

const AUDIT_LOG = [];
const HMAC_SECRET = process.env.WEBHOOK_SECRET || crypto.randomBytes(32).toString('hex');

class AuditEntry {
  constructor(timestamp, actor, action, resource, metadata) {
    this.id = crypto.randomUUID();
    this.timestamp = timestamp;
    this.actor = actor;
    this.action = action;
    this.resource = resource;
    this.metadata = metadata;
    this.integrity = this._computeIntegrity();
  }

  _computeIntegrity() {
    const payload = `${this.id}|${this.timestamp}|${this.actor}|${this.action}|${this.resource}`;
    return crypto.createHmac('sha256', HMAC_SECRET).update(payload).digest('hex');
  }

  serialize() {
    return JSON.stringify({
      id: this.id,
      timestamp: this.timestamp,
      actor: this.actor,
      action: this.action,
      resource: this.resource,
      metadata: this.metadata,
      integrity: this.integrity
    });
  }
}

function sanitizeHeaderValue(value) {
  // Remove null bytes and control characters below 0x20
  // but preserve printable characters for valid header content
  if (typeof value !== 'string') return '';
  return value.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, '');
}

function normalizeFieldContent(input) {
  if (typeof input !== 'string') return String(input || '');
  // Normalize unicode and trim
  const normalized = input.normalize('NFC').trim();
  // Collapse internal whitespace sequences to single space
  return normalized.replace(/[\t ]+/g, ' ');
}

function extractPipelineContext(headers) {
  const context = {
    source: sanitizeHeaderValue(headers['x-pipeline-source'] || 'unknown'),
    buildId: sanitizeHeaderValue(headers['x-build-id'] || ''),
    triggeredBy: sanitizeHeaderValue(headers['x-triggered-by'] || 'system'),
    environment: sanitizeHeaderValue(headers['x-deploy-env'] || 'staging')
  };
  return context;
}

function createLogLine(entry, context) {
  // Format: [TIMESTAMP] ACTOR performed ACTION on RESOURCE (env=ENV, build=BUILD)
  const ts = new Date(entry.timestamp).toISOString();
  const actor = normalizeFieldContent(entry.actor);
  const action = normalizeFieldContent(entry.action);
  const resource = normalizeFieldContent(entry.resource);
  const env = normalizeFieldContent(context.environment);
  const build = normalizeFieldContent(context.buildId);
  return `[${ts}] ${actor} performed ${action} on ${resource} (env=${env}, build=${build})`;
}

function writeToTransport(logLine, res) {
  // Set response headers for audit trail confirmation
  // The log line is echoed back in a custom header for client-side verification
  const headerValue = sanitizeHeaderValue(logLine);
  res.setHeader('X-Audit-Confirmation', headerValue);
  res.setHeader('Content-Type', 'application/json');
}

function handleWebhook(req, res) {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    try {
      const payload = JSON.parse(body);
      const context = extractPipelineContext(req.headers);

      // Validate required fields
      if (!payload.actor || !payload.action || !payload.resource) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Missing required fields' }));
        return;
      }

      const entry = new AuditEntry(
        Date.now(),
        payload.actor,
        payload.action,
        payload.resource,
        payload.metadata || {}
      );

      AUDIT_LOG.push(entry);
      const logLine = createLogLine(entry, context);
      writeToTransport(logLine, res);

      res.writeHead(201);
      res.end(JSON.stringify({
        status: 'logged',
        auditId: entry.id,
        logEntry: logLine
      }));
    } catch (e) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal error' }));
    }
  });
}

function handleGetLogs(req, res) {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const since = parseInt(url.searchParams.get('since') || '0', 10);
  const filtered = AUDIT_LOG.filter(e => e.timestamp >= since);

  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ entries: filtered.map(e => JSON.parse(e.serialize())) }));
}

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/v1/audit/webhook') {
    handleWebhook(req, res);
  } else if (req.method === 'GET' && req.url?.startsWith('/api/v1/audit/logs')) {
    handleGetLogs(req, res);
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(process.env.PORT || 8443, () => {
  console.log(`Audit service listening on port ${process.env.PORT || 8443}`);
});

module.exports = { server, AuditEntry, sanitizeHeaderValue, normalizeFieldContent };
